  --rose-green:#4a7c59;
  --rose-green-light:#5a9c69;
  --rose-gold:#b8860b;
  --rose-gold-light:#d4a84b;
  --rose-text:#3d2c29;
  --rose-text-muted:#6b5a56;
  --rose-border:#e8d5c4;
  --rose-white:#ffffff;
  --rose-shadow:0 8px 32px rgba(164,72,84,0.12);
  --rose-shadow-lg:0 16px 48px rgba(164,72,84,0.16);
  --rose-radius:16px;
  --rose-radius-lg:24px;
  min-height:100vh;
  background:linear-gradient(180deg,var(--rose-cream) 0%,var(--rose-blush) 50%,var(--rose-cream) 100%);
  font-family:'Lato',sans-serif;
  color:var(--rose-text);
  position:relative;
  overflow:hidden;
  padding:40px 24px;
}

.mfp.rose-festival *{box-sizing:border-box}

.mfp.rose-festival .rose-petals{
  position:absolute;
  inset:0;
  pointer-events:none;
  z-index:0;
  overflow:hidden;
}

.mfp.rose-festival .petal{
  position:absolute;
  width:20px;
  height:24px;
  background:linear-gradient(135deg,var(--rose-pink-light) 0%,var(--rose-pink) 100%);
  border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;
  opacity:.3;
  animation:petal-fall linear infinite;
}

.mfp.rose-festival .petal::before{
  content:'';
  position:absolute;
  inset:20%;
  background:rgba(255,255,255,.3);
  border-radius:inherit;
}

.mfp.rose-festival .p1{left:10%;animation-duration:15s;animation-delay:0s}
.mfp.rose-festival .p2{left:25%;animation-duration:18s;animation-delay:2s}
.mfp.rose-festival .p3{left:40%;animation-duration:12s;animation-delay:4s}
.mfp.rose-festival .p4{left:55%;animation-duration:20s;animation-delay:1s}
.mfp.rose-festival .p5{left:70%;animation-duration:14s;animation-delay:3s}
.mfp.rose-festival .p6{left:85%;animation-duration:16s;animation-delay:5s}
.mfp.rose-festival .p7{left:5%;animation-duration:22s;animation-delay:6s}
.mfp.rose-festival .p8{left:95%;animation-duration:13s;animation-delay:2.5s}

@keyframes petal-fall{
  0%{top:-10%;transform:rotate(0deg) translateX(0)}
  25%{transform:rotate(90deg) translateX(30px)}
  50%{transform:rotate(180deg) translateX(-20px)}
  75%{transform:rotate(270deg) translateX(25px)}
  100%{top:110%;transform:rotate(360deg) translateX(0)}
}

